demo_in = G['Demo pair 1 input']
demo_out = G['Demo pair 1 output']

def transform(row):
    """Fill 2s by mirroring within the SAME row's left/right halves, THEN mirror the whole row"""
    n_left = 12

    # Copy non-2 values only
    filled_left = []
    for i in range(n_left):
        if row[i] == 2:
            filled_left.append(None)  # Unknown
        else:
            filled_left.append(row[i])

    filled_right = []
    for i in range(n_left):
        j = i + n_left
        if row[j] == 2:
            filled_right.append(None)
        else:
            filled_right.append(row[j])

    # Now use mirroring to fill unknowns
    # Left-mirror within left half
    for i in range(n_left):
        if filled_left[i] is None:
            mirrored_i = n_left - 1 - i
            if filled_left[mirrored_i] is not None:
                filled_left[i] = filled_left[mirrored_i]

    # Right-mirror within right half  
    for i in range(n_left):
        if filled_right[i] is None:
            mirrored_i = n_left - 1 - i
            if filled_right[mirrored_i] is not None:
                filled_right[i] = filled_right[mirrored_i]

    # Combine into full row
    full_row = filled_left + filled_right

    # Final step: make symmetric by taking left and mirroring
    return full_row[:n_left] + full_row[:n_left][::-1]

# Test on demo
predicted = [transform(demo_in[r]) for r in range(24)]

all_match = True
for r in range(24):
